scripts.Begin.txt:
	SetPlayerDir(3);
	SetPlayerPos(24, 39);
	SetNpcActionFile("杨影枫", 0, "mpc001_跪.asf");
	SetNpcActionFile("杨影枫", 1, "mpc001_跪.asf");
	PlayMusic("Mc001.mp3");
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	FadeIn();
	//Say("<color=Red>十年后……");
	Sleep(500);
	Say("杨影枫：时间过得真快啊，爹，一眨眼，十年过去了。", 2_;
	Say("杨影枫：十年前的那一幕，孩儿怎么也忘不了。这十年来，孩儿一直谨记你的遗嘱，不问世事，潜心练习家传武功，为的就是将来能完成你的遗愿。", 2);
	Say("杨影枫：如今孩儿的武功已经小有所成，准备下山到江湖上去闯荡一番，特来向你辞行。", 2);
	Say("杨影枫：爹，你放心吧，孩儿不会让你失望的，假以时日，孩儿一定会成为<color=Red>武功天下第一<color=Black>！",	2);
//	Talk(0,0);
	SetNpcActionFile("杨影枫", 0, "npc006_st2.asf");
	SetNpcActionFile("杨影枫", 1, "npc006_sst2.asf");
	NpcSpecialAction("杨影枫","mpc001.asf");
	Sleep(1500);
	AddToMemo(90000);
	SetPlayerState(0);
	Assign($Event, 10);
	Assign($Result, 0);
	Assign($EvilVal, 1000);
	Assign($SenseVal, 1000);
	PlayerGoto(24, 43);
	SetPlayerDir(0);
	EquipGoods(1, 5);
	Say("欢迎进入剑侠的世界，你将在这个世界里完成一段关于月影的传说——");
	Choose("请选择游戏的难易：", "难", "易", $Level);
	If ($Level == 0) @Level;
	SetLevelFile("Level-easy.ini");
	SetNpcLevel("杨影枫", 5);
	Goto @Begin;
@Level:
	SetLevelFile("Level-hard.ini");
	Goto @Begin;
@Begin:	
	Return;

scripts.眉儿对话.txt:
	If ($Event == 1806) @1806;//结局2月眉儿决斗
	Return;

@1806:
	StopMusic();
	Say("杨影枫：月眉儿！你为什么要绑架纳兰真和蔷薇？",6);
	Say("月眉儿：杨影枫，如果我说她们被绑架跟我无关，你相信吗？",22);
	Say("杨影枫：不信！这是紫轩亲眼所见，你不是还派人去让我用《武道德经》到飞龙堡换人吗？",6);
	Say("月眉儿：我根本没有叫人去过悲魔山庄。",22);
	Say("杨影枫：你还想抵赖？实话告诉你，我根本没有什么《武道德经》。你快把真儿给我交出来！",6);
	Say("月眉儿：哼！杨影枫，你欺人太甚，我爹当年本不愿和你爹比武，但是你爹却苦苦相逼，结果害得我家破人亡……",26);
	Say("杨影枫：上一代的恩怨……我爹是有些不对……但你如果想给你爹报仇……也不必用如此卑鄙的手段",6);
	Say("月眉儿：如今，你又不分青红皂白跑到飞龙堡，打死打伤我无数弟子，我今天就是特地约你来此做一个了断的。",26);
	Say("杨影枫：你先把纳兰真放了再说。",6);
	Say("月眉儿：闲话少说……纳兰真已经被我杀了，有本事你就杀了我替她报仇吧！",26);
	Say("杨影枫：什么！？……真儿！……",6);
	SetNpcRelation("月眉儿",1);
	SetMapTrap(1,"");
	PlayMusic("mc027.mp3");
	Return;

scripts.眉儿死亡.txt:
	If ($Event == 1806) @1806;//结局2月眉儿决斗
	Return;

@1806:
	StopMusic();
	FadeOut();
	DelNpc("月眉儿");
	ClearBody();
	SaveObj();
	AddNpc("月眉儿.ini",8,18,7);
	AddNpc("纳兰真.ini",9,33,4);
	SetNpcScript("纳兰真","真儿对话.txt");
	SetNpcActionFile("月眉儿",0,"mpc091.asf");
	SetNpcActionFile("月眉儿",1,"mpc091.asf");
	SetPlayerPos(8,17);
	SetPlayerDir(1);
	Say("一场激战……月眉儿被杨影枫打成重伤");
	PlayMusic("mc013.mp3");
	FadeIn();
	Say("杨影枫：月眉儿！我再问一遍，纳兰真是不是真的被你杀了？",6);
	Say("月眉儿：杨影枫……少说废话……你快动手吧！",26);
	Say("杨影枫：月眉儿……我要杀了你……给我的真儿报仇！",6);
	Say("月眉儿：（闭上了眼睛）……",24);
	Say("纳兰真：不要啊！影枫哥！",12);
	SetPlayerDir(0);
	Say("杨影枫：真儿！",4);
	NpcGotoEx("纳兰真",9,31);
	PlayerRunTo(9,29);
	Watch("纳兰真","杨影枫",0);
	Say("杨影枫：真儿！原来你没死！",4);
	Say("纳兰真：影枫哥！你为什么要杀月姑娘？",11);
	Say("杨影枫：真儿！不是她把你绑架了吗？",2);
	Say("纳兰真：影枫哥！你太糊涂了……",11);
	Say("杨影枫：真儿！这到底是怎么回事？",4);
	Say("纳兰真：先别说了，救月姑娘要紧！",11);
	NpcGotoEx("纳兰真",8,18);
	Sleep(500);
	PlayerGotoEx(8,19);
	Sleep(500);
	FadeOut();
	SetNpcKind("纳兰真",3);
	SetMapTrap(1,"trap01.txt");
	Say("杨影枫和纳兰真带着受伤的月眉儿来到了惠安镇的王大夫处……");
	LoadMap("map_012_惠安镇.map");
	AddNpc("惠安镇大夫.ini",79,31,7);
	AddObj("躺着的月眉儿.ini",80,27,0);
	SetObjOfs("躺着的月眉儿",-10,10);
	SetPlayerPos(80,32);
	SetPlayerDir(4);
	SetNpcKind("纳兰真",1);
	SetNpcPos("纳兰真",80,33);
	SetNpcDir("纳兰真",4);
	FadeIn();
	Say("杨影枫：大夫……她的伤势到底怎么样？",8);
	Say("王大夫：这位姑娘受了极重的内伤，我看恐怕凶多吉少，你们还是早点替她准备后事吧。",53);
	Say("纳兰真：影枫哥……你一定要想办法救救月姑娘呀……",14);
	Watch("纳兰真","杨影枫",0);
	Say("杨影枫：真儿……我们去药王谷找胡神医想想办法吧。",2);
	SetNpcKind("纳兰真",3);
	FadeOut();
	Say("杨影枫和纳兰真带着受伤的月眉儿来到了药王谷……");
	LoadMap("map_063_药王谷.map");
	AddNpc("胡神医.ini",35,75,3);
	AddObj("躺着的眉儿.ini",35,74,0);
	SetObjOfs("躺着的眉儿",0,-30);
	SetPlayerPos(35,76);
	SetPlayerDir(4);
	SetNpcPos("纳兰真",35,77);
	FadeIn();
	Say("杨影枫：胡神医，她还有救吗？",8);
	Say("胡神医：这位姑娘的伤势很重，我只能暂时保住她的性命。",45);
	Say("杨影枫：胡神医，那如何才能治好她呢？",5);
	Say("胡神医：要想彻底医好她，必须以先天无极真气打通她全身的经脉，然后用<color=Red>银丝草<color=Blue>十二株<color=Black>煎服三日方能痊愈。",45);
	Say("纳兰真：<color=Red>银丝草<color=Black>在忘忧岛可以找到，但是谁能用无极真气来替月姑娘打通全身的经脉呢？",15);
	Say("胡神医：施展此功救人者，必须有十年以上先天无极真气的修为，否则不但不能救人，自身亦难免受害。",45);
	Say("杨影枫：不知当世谁能有如此功力？还请神医指点。",2);
	Say("胡神医：据我所知，只有天山落叶谷的<color=Red>孟知秋<color=Black>才有如此修为。",45);
	Say("杨影枫：太好了，真儿，我们现在就去落叶谷。",3);
	Say("胡神医：不过……施展此功救人必定大耗真气，我看那孟知秋未必肯帮你这个忙。",45);
	Say("杨影枫：这个不用神医操心，我自有办法。",3);
	Say("杨影枫：真儿，我们走吧。",2);
	Say("纳兰真：嗯……影枫哥",9);
	FadeOut();
	Say("几天后，三人来到了天山落叶谷……");
	LoadMap("map_033_落叶谷.map");
	LoadNpc("map033.npc");
	LoadObj("map033_obj.obj");
	AddObj("躺着的月眉儿.ini",25,98,0);
	SetObjOfs("躺着的月眉儿",-10,-30);
	SetNpcKind("纳兰真",1);
	SetNpcPos("纳兰真",24,99);
	SetNpcDir("纳兰真",5);
	SetNpcPos("孟知秋",27,105);
	SetNpcDir("孟知秋",1);
	SetPlayerPos(26,107);
	SetPlayerDir(5);
	DelNpc("蔷薇");
	SetMapTrap(1,"");
	FadeIn();
	
	Say("孟知秋：这个受伤的姑娘不是飞龙堡的少堡主月眉儿吗？",42);
	Say("杨影枫：不错……她就是月眉儿。",2);
	Say("孟知秋：她怎么会伤的这么重？",42);
	Say("杨影枫：是我错手不慎打伤的……",5);
	Say("杨影枫将事情经过讲述了一遍");
	Say("孟知秋：你可知她为什么要绑架小女吗？",42);
	Say("杨影枫：我想绑架蔷薇小姐的事，月眉儿可能并不知情。",2);
	Say("孟知秋：杨少侠，要老夫救人也可以，不过你得答应我一件事。",43);
	Say("杨影枫：什么事？晚辈一定尽力而为。",2);
	Say("孟知秋：只要你答应老夫和蔷薇成亲就可以了，怎么样？不难办吧。",43);
	Say("杨影枫：这个……",4);
	Say("孟知秋：杨少侠，你救过小女，我本不该再提什么条件，但是为了薇儿的幸福，老夫也只好出此下策，望少侠能理解老夫的苦心。",42);
	
	Choose("杨影枫：","前辈……晚辈恕难从命……","前辈……让我考虑一下……",$wangwei);
//	Choose("是否答应孟知秋和蔷薇成亲？","A、不答应","B、再考虑一下",$wangwei);
	If ($wangwei == 1) @kaolu;

//	Say("杨影枫：前辈……晚辈恕难从命……",7);
	Say("孟知秋：杨影枫，论相貌、论武功、小女有哪点配不上你？你为何总是推三阻四呢？",43);
	Say("杨影枫：不……晚辈只是不想辜负真儿姑娘对我的一片深情……",7);
	Say("孟知秋：我给你一天的时间，你好好考虑一下吧。",42);
	Return;
	
@kaolu:
//	Say("杨影枫：前辈……让我考虑一下……",7);
	Say("孟知秋：好，我给你一天时间，你好好考虑一下吧。",42);
	Return;

